\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.76\textwidth,
    xmin=-1, xmax=1,
    ymin=-6, ymax=6,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1},
    ytick={-6,0,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={small window}
]
\addplot[very thick, domain=-1:1, samples=120] {x^3-6*x};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=\textwidth,
    height=0.76\textwidth,
    xmin=-3, xmax=3,
    ymin=-12, ymax=12,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,-2,-1,0,1,2,3},
    ytick={-12,-6,0,6,12},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    title={wider window}
]
\addplot[very thick, domain=-3:3, samples=200] {x^3-6*x};
\addplot[only marks, mark=*] coordinates {(-1.414,5.657) (1.414,-5.657)};
\node[anchor=south east] at (axis cs:-1.414,5.657) {local max};
\node[anchor=north west] at (axis cs:1.414,-5.657) {local min};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.66\textwidth,
    height=0.45\textwidth,
    xmin=-1, xmax=3,
    ymin=-0.5, ymax=4.5,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-1,0,1,2,3},
    ytick={0,1,2,3,4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[very thick, domain=-1:3, samples=2] {x+1};
\addplot[only marks, mark=o, mark size=3pt, thick] coordinates {(1,2)};
\node[anchor=west] at (axis cs:1,2) {hole};
\node[anchor=west] at (axis cs:1.7,3.1) {\(y=x+1,\ x\neq1\)};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.82\textwidth,
    height=0.42\textwidth,
    xmin=0, xmax=0.4,
    ymin=-1.25, ymax=1.25,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={},
    xtick={0,0.1,0.2,0.3,0.4},
    ytick={-1,0,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, fill=none, at={(0.5,-0.20)}, anchor=north, legend columns=2, font=\small}
]
\addplot[very thick, domain=0:0.4, samples=300] {sin(deg(100*x))};
\addlegendentry{many samples}
\addplot[thick, dashed, mark=*] coordinates {
    (0,0)
    (0.04,{sin(deg(4))})
    (0.08,{sin(deg(8))})
    (0.12,{sin(deg(12))})
    (0.16,{sin(deg(16))})
    (0.20,{sin(deg(20))})
    (0.24,{sin(deg(24))})
    (0.28,{sin(deg(28))})
    (0.32,{sin(deg(32))})
    (0.36,{sin(deg(36))})
    (0.40,{sin(deg(40))})
};
\addlegendentry{few samples}
\end{axis}
\end{tikzpicture}
